/* Read Free — service worker. GENERATED by scripts/build.mjs from scripts/sw.template.js; do not edit sw.js. */

const VERSION = '__VERSION__'
const CACHE = `reader-shell-${VERSION}`
const PRECACHE = __PRECACHE__ // { url: sha256 }

const hex = buf => [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('')

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    // cache: 'reload' bypasses the HTTP cache, and every file must match this
    // version's fingerprint. Right after a deploy a CDN can still hand out some
    // old files; then this update fails, the current version keeps working, and
    // the browser tries again later.
    const files = await Promise.all(Object.entries(PRECACHE).map(async ([url, expected]) => {
      const request = new Request(url, { cache: 'reload' })
      const response = await fetch(request)
      if (!response.ok) throw new Error(`${url}: ${response.status}`)
      const actual = hex(await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer()))
      if (actual !== expected) throw new Error(`${url} is from a different version`)
      return [request, response]
    }))
    const cache = await caches.open(CACHE)
    await Promise.all(files.map(([request, response]) => cache.put(request, response)))
  })())
  // First install activates immediately; updates wait for the user to accept (see sw-client.js).
  // The legacy 1.x worker ("reader-vN" caches) has no update prompt, so replace it right away.
  event.waitUntil((async () => {
    const legacy = (await caches.keys()).some(k => /^reader-v\d+$/.test(k))
    if (!self.registration.active || legacy) await self.skipWaiting()
  })())
})

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keys = await caches.keys()
    await Promise.all(keys.filter(k => k.startsWith('reader-') && k !== CACHE && k !== 'reader-share').map(k => caches.delete(k)))
    await self.clients.claim()
  })())
})

self.addEventListener('message', event => {
  if (event.data === 'skip-waiting') self.skipWaiting()
})

self.addEventListener('fetch', event => {
  const { request } = event
  const url = new URL(request.url)

  // Web Share Target (Android): stash shared files, then let the app import them.
  if (request.method === 'POST' && url.pathname.endsWith('/share-target')) {
    event.respondWith((async () => {
      const form = await request.formData()
      const cache = await caches.open('reader-share')
      for (const file of form.getAll('books')) {
        if (!(file instanceof File)) continue
        await cache.put(`./shared/${Date.now()}-${encodeURIComponent(file.name)}`,
          new Response(file, { headers: { 'Content-Type': file.type || 'application/octet-stream', 'X-File-Name': encodeURIComponent(file.name) } }))
      }
      return Response.redirect('./#/library?shared=1', 303)
    })())
    return
  }

  if (request.method !== 'GET') return
  if (url.origin !== self.location.origin) return // libraries are fetched directly by the app

  if (request.mode === 'navigate') {
    const scope = new URL(self.registration.scope)
    const rest = url.pathname.slice(scope.pathname.length)
    // Shared quote links (readfree.app/q/…) open straight in the app, even offline.
    if (rest.startsWith('q/')) {
      event.respondWith(Response.redirect(new URL(`#/q/${rest.slice(2)}${url.search}`, scope).href, 302))
      return
    }
    // Other server paths (preview images, oEmbed) aren't the app.
    if (rest && rest !== 'index.html') return
    // App navigations get the cached shell (the app routes with #hash).
    event.respondWith((async () => {
      const cached = await caches.match('./index.html', { cacheName: CACHE })
      if (cached) return cached
      return fetch(request)
    })())
    return
  }

  // Starter-shelf book files are stored in IndexedDB by the app; never cache them twice.
  if (url.pathname.includes('/books/')) return

  event.respondWith((async () => {
    const cached = await caches.match(request, { cacheName: CACHE, ignoreSearch: true })
    if (cached) return cached
    return fetch(request)
  })())
})
